// Exact GCC 2 stl_tree.h _M_insert body with released stringx/script_object types.
class string_buf;
class stringx {
protected:
  char *chars;
  string_buf *my_buf;
public:
  friend bool operator<(const stringx &, const stringx &);
};
class script_object;

template<class T> struct my_allocator {};
template<class T1, class T2> struct pair {
  T1 first;
  T2 second;
};
typedef pair<const stringx, script_object *> value_type;

struct _Rb_tree_node_base {
  int color;
  _Rb_tree_node_base *parent;
  _Rb_tree_node_base *left;
  _Rb_tree_node_base *right;
};
struct rb_node : _Rb_tree_node_base { value_type value_field; };

extern "C" void rebalance(_Rb_tree_node_base *, _Rb_tree_node_base *&)
  __asm__("_Rb_tree_rebalance__FP18_Rb_tree_node_baseRP18_Rb_tree_node_base");
extern "C" rb_node *create_node(void *, const value_type &)
  __asm__("_M_create_node__t8_Rb_tree5Z7stringxZt4pair2ZC7stringxZP13script_objectZt10_Select1st1Zt4pair2ZC7stringxZP13script_objectZt4less1Z7stringxZt12my_allocator1ZP13script_objectRCt4pair2ZC7stringxZP13script_object");

struct iterator {
  _Rb_tree_node_base *_M_node;
  iterator(_Rb_tree_node_base *x) : _M_node(x) {}
};
struct tree {
  _Rb_tree_node_base *_M_header;
  unsigned int _M_node_count;
};

extern "C" iterator tree_insert(tree *, _Rb_tree_node_base *, _Rb_tree_node_base *, const value_type &)
  __asm__("_M_insert__t8_Rb_tree5Z7stringxZt4pair2ZC7stringxZP13script_objectZt10_Select1st1Zt4pair2ZC7stringxZP13script_objectZt4less1Z7stringxZt12my_allocator1ZP13script_objectP18_Rb_tree_node_baseT1RCt4pair2ZC7stringxZP13script_object");

iterator tree_insert(tree *self, _Rb_tree_node_base *x_, _Rb_tree_node_base *y_, const value_type& v) {
  rb_node *x = (rb_node *)x_;
  rb_node *y = (rb_node *)y_;
  rb_node *z;
  if (y == (rb_node *)self->_M_header || x != 0 || v.first < y->value_field.first) {
    z = create_node(self, v);
    y->left = z;
    if (y == (rb_node *)self->_M_header) {
      self->_M_header->parent = z;
      self->_M_header->right = z;
    } else if (y == (rb_node *)self->_M_header->left)
      self->_M_header->left = z;
  } else {
    z = create_node(self, v);
    y->right = z;
    if (y == (rb_node *)self->_M_header->right)
      self->_M_header->right = z;
  }
  z->parent = y;
  z->left = 0;
  z->right = 0;
  rebalance(z, self->_M_header->parent);
  ++self->_M_node_count;
  return iterator(z);
}
